Here's how to handle each scenario with modern MSTest (3.9+) attributes:

```csharp
[TestClass]
public sealed class MyTests
{
    private readonly TestContext _testContext;
    private string? _tempFile;

    public MyTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void ReadRegistryKey_ReturnsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Setting", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void RenderFrame_WithGpu_ProducesOutput()
    {
        var result = GpuRenderer.RenderFrame();
        Assert.IsNotEmpty(result.Pixels);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task GetWeather_ReturnsForecast()
    {
        var forecast = await WeatherClient.GetAsync("Seattle", _testContext.CancellationToken);
        Assert.IsNotNull(forecast);
    }

    // 4. Temp files — TestCleanup runs even on failure
    [TestMethod]
    public void ExportReport_WritesToFile()
    {
        _tempFile = Path.GetTempFileName();

        ReportService.Export(_tempFile);

        Assert.IsNotEmpty(File.ReadAllText(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }
}
```

**Key points:**

| Scenario | Solution |
|----------|----------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` — test is skipped (not failed) on other OSes |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` — skipped when CI env vars are detected |
| Flaky API | `[Retry(3)]` — retries up to 3 times before reporting failure |
| Cleanup on failure | `[TestCleanup]` — always runs after the test, even if it throws |

`[Retry]` requires MSTest 3.9+; `[OSCondition]` and `[CICondition]` require 3.10+. Combine `[Timeout]` with `TestContext.CancellationToken` for cooperative cancellation on async tests.
